from research_sdk import Client
import json, time
c = Client()
jobs = json.load(open('/workspace/work/pilot2_jobs.json'))
deadline = time.time() + 800
while time.time() < deadline:
    sts = {m: c.status(j)['status'] for m, j in jobs.items()}
    if all(s not in ('queued','running') for s in sts.values()):
        break
    time.sleep(15)
for m, jid in jobs.items():
    res = c.status(jid)
    if res['status'] == 'ok':
        for it in res['result']['items']:
            print(f"  {m[-2:]} {it['id']:14s} score={it.get('score')} finish={it.get('finish_reason')}")
print('charged:', c.budget()[0]['charged'])
# also dev-12 pilot
j12 = json.load(open('/workspace/work/pilot_jobs.json'))['development-12']
r12 = c.status(j12)
print('dev-12 pilot:', r12['status'])
if r12['status'] == 'ok':
    json.dump({'model':'development-12','items':r12['result']['items']}, open('/workspace/work/res_pilot_12.json','w'), indent=1)
    for it in r12['result']['items']:
        print(f"  12 {it['id']:14s} score={it.get('score')} finish={it.get('finish_reason')}")
EOF",
  "description": "Wait for pilot2 and dev-12 results"
}

